import { legacy_createStore, combineReducers } from 'redux';

const wallet = (state = { balance: 0 }, action) => {
  switch (action.type) {
    case 'wallet/deposited':
      return { balance: state.balance + action.payload };
    case 'wallet/withdrawn':
      return action.payload > state.balance
        ? state
        : { balance: state.balance - action.payload };
    default:
      return state;
  }
};

const store = legacy_createStore(combineReducers({ wallet }));
let calls = 0;
store.subscribe(() => calls++);

store.dispatch({ type: 'wallet/deposited', payload: 500 });
